using CarCareTracker.External.Interfaces;
using CarCareTracker.Models;
using Npgsql;
using System.Text.Json;

namespace CarCareTracker.External.Implementations
{
    public class PGBudgetDataAccess : IBudgetDataAccess
    {
        private NpgsqlDataSource pgDataSource;
        private readonly ILogger<PGBudgetDataAccess> _logger;
        private static string profileTable = "budget_profiles";
        private static string auditTable = "budget_audit";
        public PGBudgetDataAccess(IConfiguration config, ILogger<PGBudgetDataAccess> logger)
        {
            pgDataSource = NpgsqlDataSource.Create(config["POSTGRES_CONNECTION"] ?? string.Empty);
            _logger = logger;
            try
            {
                string initCMD = $"CREATE SCHEMA IF NOT EXISTS app; " +
                    $"CREATE TABLE IF NOT EXISTS app.{profileTable} (id INT primary key, data jsonb not null); " +
                    $"CREATE TABLE IF NOT EXISTS app.{auditTable} (id INT GENERATED BY DEFAULT AS IDENTITY primary key, householdId INT not null, data jsonb not null); " +
                    $"CREATE INDEX IF NOT EXISTS {auditTable}_household_idx ON app.{auditTable} (householdId)";
                using (var ctext = pgDataSource.CreateCommand(initCMD))
                {
                    ctext.ExecuteNonQuery();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
        }
        public BudgetProfile? GetBudgetProfile(int householdId)
        {
            try
            {
                string cmd = $"SELECT data FROM app.{profileTable} WHERE id = @id";
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    ctext.Parameters.AddWithValue("id", householdId);
                    using (NpgsqlDataReader reader = ctext.ExecuteReader())
                        while (reader.Read())
                        {
                            return JsonSerializer.Deserialize<BudgetProfile>(reader["data"] as string ?? "{}");
                        }
                }
                return null;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return null;
            }
        }
        public bool SaveBudgetProfile(BudgetProfile profile)
        {
            try
            {
                string cmd = $"INSERT INTO app.{profileTable} (id, data) VALUES(@id, CAST(@data AS jsonb)) ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data";
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    ctext.Parameters.AddWithValue("id", profile.Id);
                    ctext.Parameters.AddWithValue("data", JsonSerializer.Serialize(profile));
                    return ctext.ExecuteNonQuery() > 0;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return false;
            }
        }
        public bool AddAuditEntry(BudgetAuditEntry entry)
        {
            try
            {
                string cmd = $"INSERT INTO app.{auditTable} (householdId, data) VALUES(@householdId, CAST(@data AS jsonb)) RETURNING id";
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    ctext.Parameters.AddWithValue("householdId", entry.HouseholdId);
                    ctext.Parameters.AddWithValue("data", "{}");
                    entry.Id = Convert.ToInt32(ctext.ExecuteScalar());
                }
                string cmdU = $"UPDATE app.{auditTable} SET data = CAST(@data AS jsonb) WHERE id = @id";
                using (var ctextU = pgDataSource.CreateCommand(cmdU))
                {
                    ctextU.Parameters.AddWithValue("id", entry.Id);
                    ctextU.Parameters.AddWithValue("data", JsonSerializer.Serialize(entry));
                    return ctextU.ExecuteNonQuery() > 0;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return false;
            }
        }
        public List<BudgetAuditEntry> GetAuditEntries(int householdId, int limit)
        {
            var results = new List<BudgetAuditEntry>();
            try
            {
                string cmd = $"SELECT data FROM app.{auditTable} WHERE householdId = @householdId ORDER BY id DESC LIMIT @limit";
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    ctext.Parameters.AddWithValue("householdId", householdId);
                    ctext.Parameters.AddWithValue("limit", limit);
                    using (NpgsqlDataReader reader = ctext.ExecuteReader())
                        while (reader.Read())
                        {
                            var entry = JsonSerializer.Deserialize<BudgetAuditEntry>(reader["data"] as string ?? "{}");
                            if (entry != null)
                            {
                                results.Add(entry);
                            }
                        }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
            return results;
        }
    }
}
